package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.StringReader;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.when;

public class ReaderBasedJsonParser_getTokenLocation_TriageGen2Test {

    private IOContext mockIoContext;
    private Object mockSource;

    @Before
    public void setUp() {
        mockIoContext = Mockito.mock(IOContext.class);
        mockSource = new Object();
        when(mockIoContext.getSourceReference()).thenReturn(mockSource);
    }

    /**
     * Helper method to instantiate ReaderBasedJsonParser via reflection 
     * because the constructor parameters are complex and internal.
     */
    private ReaderBasedJsonParser createParser(String json, JsonToken initialToken) throws Exception {
        ReaderBasedJsonParser parser = new ReaderBasedJsonParser(
                mockIoContext, 
                0, 
                new StringReader(json), 
                null, 
                null
        );

        // Use reflection to set the internal state for testing branch coverage
        setField(parser, "_currToken", initialToken);

        if (initialToken == JsonToken.FIELD_NAME) {
            setField(parser, "_nameInputTotal", 10L);
            setField(parser, "_nameInputRow", 1);
            setField(parser, "_tokenInputCol", 5);
        } else {
            setField(parser, "_tokenInputTotal", 20L);
            setField(parser, "_tokenInputRow", 2);
            setField(parser, "_tokenInputCol", 8);
        }

        return parser;
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testGetTokenLocation_WhenTokenIsFieldName() throws Exception {
        // Branch: if (_currToken == JsonToken.FIELD_NAME)
        ReaderBasedJsonParser parser = createParser("{\"name\": 1}", JsonToken.FIELD_NAME);

        JsonLocation location = parser.getTokenLocation();

        assertNotNull(location);
        assertEquals(mockSource, location.getSourceRef());
        assertEquals(-1L, location.getByteOffset());
        assertEquals(1, location.getByteOffset()); // Note: Depending on internal implementation of JsonLocation, 
                                                  // we check the values passed to constructor
        // Based on the code: new JsonLocation(src, -1L, _nameInputTotal, _nameInputRow, _tokenInputCol);
        // Since we can't easily access private fields of JsonLocation without reflection, 
        // we verify the logic flow via the properties.
        // In Jackson, JsonLocation stores these as offset, line, column.
    }

    @Test
    public void testGetTokenLocation_WhenTokenIsNotFieldName() throws Exception {
        // Branch: else (default return)
        ReaderBasedJsonParser parser = createParser("{\"name\": 1}", JsonToken.VALUE_STRING);

        JsonLocation location = parser.getTokenLocation();

        assertNotNull(location);
        assertEquals(mockSource, location.getSourceRef());
        // Based on the code: new JsonLocation(src, 0L, _tokenInputTotal, _tokenInputRow, getTokenColumnNr());
    }

    @Test
    public void testGetTokenLocation_WhenTokenIsStartObject() throws Exception {
        // Branch: else (default return)
        ReaderBasedJsonParser parser = createParser("{", JsonToken.START_OBJECT);

        JsonLocation location = parser.getTokenLocation();

        assertNotNull(location);
        assertEquals(mockSource, location.getSourceRef());
    }

    /**
     * This test ensures that the different branches of the if-else are hit.
     * Branch 1: _currToken == JsonToken.FIELD_NAME
     * Branch 2: _currToken != JsonToken.FIELD_NAME
     */
    @Test
    public void testGetTokenLocation_Coverage() throws Exception {
        // Test Branch 1
        ReaderBasedJsonParser parser1 = createParser("test", JsonToken.FIELD_NAME);
        JsonLocation loc1 = parser1.getTokenLocation();
        assertEquals(-1L, loc1.getByteOffset());

        // Test Branch 2
        ReaderBasedJsonParser parser2 = createParser("test", JsonToken.START_ARRAY);
        JsonLocation loc2 = parser2.getTokenLocation();
        assertEquals(0L, loc2.getByteOffset());
    }
}
